const code = ($json && $json.params && $json.params.code) ? $json.params.code.toString() : '';
const ua = (($json && $json.headers && ($json.headers['user-agent'] || $json.headers['User-Agent'])) || '').toString().toLowerCase();
const botPatterns = ['bot','crawl','spider','preview','facebookexternalhit','curl','wget','python','java/','go-http','okhttp','headless','prefetch','scan','monitor','pingdom','uptime','safelinks','outlook','gmailimageproxy'];
const esBot = !ua || !ua.includes('mozilla') || botPatterns.some(p => ua.includes(p));
return [{ json: { codigo: code, esHumano: !esBot } }];

const pc = $('Parsear Codigo').first().json;
const normaliza = (v) => (v === undefined || v === null ? '' : v.toString().trim());
const match = $input.all().find(item => normaliza(item.json['codigo']) === pc.codigo && pc.codigo !== '');
const encontrado = !!match;
const marcar = encontrado && pc.esHumano;
return [{ json: { marcar, row_number: match ? match.json.row_number : null } }];

